def run(_context):
    import adsk.core, adsk.cam
    app = adsk.core.Application.get()
    cam = adsk.cam.CAM.cast(app.activeDocument.products.itemByProductType('CAMProductType'))
    ops = {o.name:o for o in cam.setups.item(0).operations}
    feeds = {
      "Face Top":      dict(tool_feedCutting=1500, tool_feedEntry=1000, tool_feedExit=1000, tool_feedPlunge=400, tool_feedRamp=600, tool_feedTransition=1500, tool_feedRetract=400),
      "Pocket Rough":  dict(tool_feedCutting=1800, tool_feedEntry=1000, tool_feedExit=1000, tool_feedPlunge=400, tool_feedRamp=800, tool_feedTransition=1800, tool_feedRetract=400),
      "Pocket Finish": dict(tool_feedCutting=1200, tool_feedEntry=800,  tool_feedExit=800,  tool_feedPlunge=300, tool_feedRamp=600, tool_feedTransition=1200, tool_feedRetract=300),
      "Outer Profile": dict(tool_feedCutting=1000, tool_feedEntry=700,  tool_feedExit=700,  tool_feedPlunge=300, tool_feedRamp=500, tool_feedTransition=1000, tool_feedRetract=300),
    }
    for name, d in feeds.items():
        op = ops[name]
        for k, v in d.items():
            p = op.parameters.itemByName(k)
            if p: p.expression = "%d mm/min" % v
    for name in feeds:
        p = mb.list_params(name)
        print(name, {k:p[k]['expression'] for k in ("tool_feedCutting","tool_feedPlunge","tool_feedRamp")})

